'use strict';
/* GOLD BIG MOVE LAB — research only, NOT live.
   Purpose: find robust M5 expansion/continuation rules for BUY+SELL on the same 1Y Dukascopy dataset.
   Causal indicators only; next-bar-open entry; SL checked before TP on ambiguous bars.
   DEV=first 75%, HOLD=last 25%. Candidate selection uses DEV only; HOLD is printed untouched.
*/
const fs=require('fs');
const FILE='data/xauusd-m5-dukascopy.json';
if(!fs.existsSync(FILE)){console.error('❌ Missing '+FILE);process.exit(1)}
const raw=JSON.parse(fs.readFileSync(FILE,'utf8'));
const rows=Array.isArray(raw)?raw:(raw.candles||raw.data||[]);
const M=rows.map(x=>({t:+new Date(x.t||x.time||x.timestamp||x.datetime),o:+(x.o??x.open),h:+(x.h??x.high),l:+(x.l??x.low),c:+(x.c??x.close),v:+(x.v??x.volume??0)})).filter(x=>Number.isFinite(x.t+x.o+x.h+x.l+x.c)).sort((a,b)=>a.t-b.t);
function ema(vals,n){const out=Array(vals.length).fill(null),k=2/(n+1);let s=0;for(let i=0;i<vals.length;i++){if(i<n){s+=vals[i];if(i===n-1)out[i]=s/n}else out[i]=vals[i]*k+out[i-1]*(1-k)}return out}
function atr(c,n=14){const tr=c.map((x,i)=>i?Math.max(x.h-x.l,Math.abs(x.h-c[i-1].c),Math.abs(x.l-c[i-1].c)):x.h-x.l),out=Array(c.length).fill(null);let s=0;for(let i=0;i<tr.length;i++){if(i<n){s+=tr[i];if(i===n-1)out[i]=s/n}else out[i]=(out[i-1]*(n-1)+tr[i])/n}return out}
function adx(c,n=14){const N=c.length,tr=Array(N).fill(0),pdm=Array(N).fill(0),mdm=Array(N).fill(0),dx=Array(N).fill(null),out=Array(N).fill(null);for(let i=1;i<N;i++){tr[i]=Math.max(c[i].h-c[i].l,Math.abs(c[i].h-c[i-1].c),Math.abs(c[i].l-c[i-1].c));const up=c[i].h-c[i-1].h,dn=c[i-1].l-c[i].l;pdm[i]=up>dn&&up>0?up:0;mdm[i]=dn>up&&dn>0?dn:0}let st=0,sp=0,sm=0;for(let i=1;i<N;i++){if(i<=n){st+=tr[i];sp+=pdm[i];sm+=mdm[i];if(i===n){const p=100*sp/st,m=100*sm/st;dx[i]=100*Math.abs(p-m)/(p+m||1)}}else{st=st-st/n+tr[i];sp=sp-sp/n+pdm[i];sm=sm-sm/n+mdm[i];const p=100*sp/st,m=100*sm/st;dx[i]=100*Math.abs(p-m)/(p+m||1)}}for(let i=2*n-1;i<N;i++){if(i===2*n-1){let s=0;for(let j=n;j<=i;j++)s+=dx[j]||0;out[i]=s/n}else out[i]=(out[i-1]*(n-1)+(dx[i]||0))/n}return out}
const C=M.map(x=>x.c),E20=ema(C,20),E50=ema(C,50),A=atr(M,14),D=adx(M,14);
const split=Math.floor(M.length*.75);
function run(p,lo=60,hi=M.length-2){const tr=[];let open=null;for(let i=lo;i<=hi;i++){if(open){const b=M[i];let why=null,px=null;if(open.side==='BUY'){if(b.l<=open.sl){why='SL';px=open.sl}else if(b.h>=open.tp){why='TP';px=open.tp}}else{if(b.h>=open.sl){why='SL';px=open.sl}else if(b.l<=open.tp){why='TP';px=open.tp}}if(!why&&i-open.ei>=p.hold){why='TIME';px=b.c}if(why){const r=open.side==='BUY'?(px-open.entry)/(open.entry-open.sl):(open.entry-px)/(open.sl-open.entry);tr.push({...open,xi:i,r,why});open=null}continue}if(i<55||!A[i]||!D[i]||!E20[i]||!E50[i])continue;const b=M[i],range=b.h-b.l,body=Math.abs(b.c-b.o);if(!(range>0))continue;const bodyAtr=body/A[i],rangeAtr=range/A[i],bodyFrac=body/range,closePos=(b.c-b.l)/range;let hh=-Infinity,ll=Infinity;for(let j=i-p.look;j<i;j++){hh=Math.max(hh,M[j].h);ll=Math.min(ll,M[j].l)}const atrAvg=(()=>{let s=0,n=0;for(let j=i-30;j<i;j++)if(A[j]){s+=A[j];n++}return n?s/n:null})();if(!atrAvg)continue;const exp=A[i]/atrAvg,upTrend=E20[i]>E50[i]&&E20[i]>E20[i-3],dnTrend=E20[i]<E50[i]&&E20[i]<E20[i-3];let side=null;if(bodyAtr>=p.bodyAtr&&rangeAtr<=p.maxRange&&bodyFrac>=p.bodyFrac&&exp>=p.exp&&D[i]>=p.adx){if(upTrend&&b.c>hh&&closePos>=p.closePos)side='BUY';if(dnTrend&&b.c<ll&&(1-closePos)>=p.closePos)side='SELL'}if(!side)continue;const entry=M[i+1].o;if(!Number.isFinite(entry))continue;const risk=Math.max(p.slAtr*A[i],.01);const tpRisk=p.rr*risk;open={side,si:i,ei:i+1,entry,sl:side==='BUY'?entry-risk:entry+risk,tp:side==='BUY'?entry+tpRisk:entry-tpRisk,t:M[i+1].t}}
return tr}
function st(a){let gp=0,gl=0,w=0,peak=0,eq=0,dd=0,ls=0,maxLs=0;for(const x of a){eq+=x.r;if(x.r>0){gp+=x.r;w++;ls=0}else if(x.r<0){gl+=-x.r;ls++;maxLs=Math.max(maxLs,ls)}peak=Math.max(peak,eq);dd=Math.max(dd,peak-eq)}return{n:a.length,wr:a.length?100*w/a.length:0,pf:gl?gp/gl:Infinity,net:eq,dd,ls:maxLs}}
const grid=[];for(const bodyAtr of [.7,.9,1.1,1.3])for(const bodyFrac of [.6,.7,.8])for(const exp of [1,1.05,1.1,1.2])for(const adx of [18,22,26])for(const look of [12,20,30])for(const rr of [1,1.25,1.5])grid.push({bodyAtr,bodyFrac,exp,adx,look,rr,maxRange:2.4,closePos:.75,slAtr:1,hold:12});
const ranked=[];for(const p of grid){const a=run(p,60,split-2),s=st(a);if(s.n<35)continue;const score=s.net-1.25*s.dd+Math.min(s.pf,3)*2;ranked.push({p,s,score})}ranked.sort((a,b)=>b.score-a.score);
console.log('GOLD BIG MOVE LAB — DEV SEARCH / UNTOUCHED HOLDOUT');console.log('M5='+M.length+' | '+new Date(M[0].t).toISOString()+' → '+new Date(M.at(-1).t).toISOString());console.log('DEV candles='+split+' | HOLD candles='+(M.length-split)+' | Candidates='+grid.length+'\n');
console.log('🏆 TOP 20 DEV');for(let z=0;z<Math.min(20,ranked.length);z++){const x=ranked[z],p=x.p,s=x.s;console.log((z+1)+' | BA>='+p.bodyAtr+' BF>='+p.bodyFrac+' EXP>='+p.exp+' ADX>='+p.adx+' LOOK'+p.look+' RR'+p.rr+' | T'+s.n+' WR'+s.wr.toFixed(1)+' PF'+s.pf.toFixed(2)+' N'+(s.net>=0?'+':'')+s.net.toFixed(2)+'R DD'+s.dd.toFixed(2)+' LS'+s.ls)}
console.log('\n🔐 HOLDOUT — TOP 10 DEV CANDIDATES ONLY');for(let z=0;z<Math.min(10,ranked.length);z++){const x=ranked[z],h=st(run(x.p,split,M.length-2)),d=x.s,p=x.p;console.log((z+1)+' | BA>='+p.bodyAtr+' BF>='+p.bodyFrac+' EXP>='+p.exp+' ADX>='+p.adx+' LOOK'+p.look+' RR'+p.rr+' | DEV T'+d.n+' PF'+d.pf.toFixed(2)+' N'+d.net.toFixed(2)+' DD'+d.dd.toFixed(2)+' || HOLD T'+h.n+' WR'+h.wr.toFixed(1)+' PF'+h.pf.toFixed(2)+' N'+(h.net>=0?'+':'')+h.net.toFixed(2)+'R DD'+h.dd.toFixed(2)+' LS'+h.ls)}
console.log('\nNOTE: Research only. Do not add to live from this search. Next step is stability/walk-forward on any candidate that survives HOLD with enough trades and controlled DD.');
